"""End-to-end acceptance for JSON encode/decode generated by Oche code."""

from pathlib import Path
import subprocess
import tempfile

root = Path(__file__).resolve().parent.parent
manifest = root / "Cargo.toml"
example = root / "examples/comptime_json_oche.oche"
subprocess.run(
    ["cargo", "build", "--quiet", "--manifest-path", str(manifest), "-p", "oche"],
    check=True,
)
cli = root / "target/debug/oche"


def invoke(command: list[str], function: str, *arguments: str) -> str:
    result = subprocess.run(
        [*command, function, *arguments],
        capture_output=True,
        text=True,
        timeout=30,
        check=True,
    )
    return result.stdout.strip()

expected = '{"name":"Ada","age":37,"active":true}'
command = [str(cli), "run", str(example)]
assert invoke(command, "encode_user", "Ada", "37", "true") == expected
assert invoke(command, "round_trip", expected) == expected
assert invoke(command, "round_trip", '{"name":"Ada","age":"old","active":true}') == (
    "Expected a JSON integer"
)
assert invoke(command, "round_trip", '{"name":"Ada","active":true}') == (
    "Missing JSON field: age"
)
batch = '{"counts":[1,2,3],"labels":[["agent"],["tool","result"]]}'
assert invoke(command, "round_trip_batch", batch) == batch
assert invoke(command, "round_trip_batch", '{"counts":[1,true],"labels":[]}') == (
    "Expected a JSON integer"
)
envelope = (
    '{"owner":{"name":"Ada","age":37,"active":true},'
    '"batches":[{"counts":[1,2],"labels":[["agent"]]}]}'
)
assert invoke(command, "round_trip_envelope", envelope) == envelope

generated = subprocess.run(
    [str(cli), "emit-dart", str(example)],
    capture_output=True,
    text=True,
    timeout=30,
    check=True,
).stdout
assert "_oche_json_object" in generated
assert "_oche_json_as_object" in generated
assert "comptime" not in generated
assert "OcheInternal" not in generated
assert "_oche_ct_" not in generated
assert "_oche_generate_json_" not in generated

with tempfile.TemporaryDirectory(prefix="oche-json-generator-aot-") as task_dir:
    executable = Path(task_dir) / "oche-json"
    subprocess.run(
        [str(cli), "build-exe", str(example), "-o", str(executable)],
        check=True,
        capture_output=True,
        text=True,
        timeout=30,
    )
    assert invoke([str(executable)], "round_trip", expected) == expected
    assert invoke([str(executable)], "round_trip_batch", batch) == batch
    assert invoke([str(executable)], "round_trip_envelope", envelope) == envelope

print("Oche-written JSON generator: encode, decode, JIT, and AOT passed")
